pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        vm.assume(true);
        try c.Initialized() {} catch { return; }
        bool reverted1;
        try c.SetMinSum(_val1) { reverted1 = false; } catch { reverted1 = true; }
        assertTrue(reverted1);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
